import { PrismaClient } from '@prisma/client';
import { randomUUID } from 'node:crypto';
import { describe, expect, it, vi } from 'vitest';
import { MistakesService } from '../src/modules/mistakes/mistakes.service';
import { StudyService } from '../src/modules/study/study.service';
import { progressiveQualitySamples } from './fixtures/progressive-quality-samples';

// Original fixtures, not generated by a paid model or a semantic difficulty benchmark.
const materials = {
  foundation: {
    ...structuredClone(progressiveQualitySamples.foundation.group),
    title: 'A working radio',
    wordOccurrences: { repair: 1 },
    sentences: [
      {
        english: 'They repair the broken radio today.',
        chinese: '他们今天修理坏掉的收音机。',
        simplified: '他们今天修理收音机。',
        grammar: 'repair 是句子的谓语动词。',
      },
      {
        english: 'Now it works again.',
        chinese: '现在它又能用了。',
        simplified: '现在它又能用了。',
        grammar: 'again 表示再次。',
      },
    ],
    questions: [
      {
        bookWordId: '',
        type: 'MEANING_RECOGNITION',
        prompt: 'What does repair mean here?',
        options: ['修理', '购买', '出售', '丢弃'],
        correctAnswers: ['修理'],
        explanation: '收音机原来坏了，现在又能工作，所以 repair 是修理。',
      },
    ],
  },
  context: progressiveQualitySamples.context.group,
  transfer: progressiveQualitySamples.transfer.group,
};

describe.skipIf(!process.env.LAB_TEST_DATABASE_URL)(
  'progressive stages and review evidence',
  () => {
    it('keeps stage materials distinct, reuses unseen groups, and respects due/mastered eligibility', async () => {
      const prisma = new PrismaClient({
        datasources: { db: { url: process.env.LAB_TEST_DATABASE_URL! } },
      });
      const suffix = randomUUID();
      const users: string[] = [];
      const caches: string[] = [];
      const signatures: string[] = [];
      let bookId: string | undefined;
      let wordId: string | undefined;
      const ai = {
        generateForUser: vi.fn(async ({ prompt }: { prompt: string }) => {
          const groups = JSON.parse(prompt.match(/^输入分组：(.*)$/m)![1]);
          const groupsOut = groups.map(
            (input: {
              index: number;
              words: Array<{ id: string }>;
              targetQuestionTypes: Record<string, string>;
            }) => {
              const id = input.words[0].id;
              const type = input.targetQuestionTypes[id];
              const stage =
                type === 'MEANING_RECOGNITION'
                  ? 'foundation'
                  : type === 'SYNONYM_REPLACEMENT'
                    ? 'context'
                    : 'transfer';
              const group = structuredClone(materials[stage]);
              group.index = input.index;
              group.questions[0].bookWordId = id;
              return group;
            },
          );
          return { choices: [{ message: { content: JSON.stringify({ groups: groupsOut }) } }] };
        }),
      };
      const service = new StudyService(
        prisma as never,
        ai as never,
        { selectedProvider: vi.fn(async () => ({ id: 'offline-fixture' })) } as never,
        new MistakesService(prisma as never),
      );
      try {
        const book = await prisma.vocabularyBook.create({
          data: {
            sourceKey: `stage-flow-${suffix}`,
            sourcePath: 'isolated-fixture',
            title: 'Stage flow fixture',
            category: 'GENERAL',
            bookWords: {
              create: {
                position: 1,
                word: {
                  create: {
                    normalized: `stage-flow-${suffix}`,
                    text: 'repair',
                    meaning: '修理',
                  },
                },
              },
            },
          },
          include: { bookWords: true },
        });
        bookId = book.id;
        wordId = book.bookWords[0].wordId;
        const bookWordId = book.bookWords[0].id;
        for (let index = 0; index < 2; index++) {
          const user = await prisma.user.create({
            data: { email: `${suffix}-${index}@example.invalid`, passwordHash: 'fixture-only' },
          });
          users.push(user.id);
          await prisma.userVocabularyBook.create({
            data: { userId: user.id, bookId, isDefault: true },
          });
        }
        for (const [stageIndex, stage] of (
          ['foundation', 'context', 'transfer'] as const
        ).entries()) {
          const linkedCaches: string[] = [];
          for (const [learnerIndex, userId] of users.entries()) {
            const where = { userId_bookWordId: { userId, bookWordId } };
            if (stageIndex > 0) {
              // Finishing the previous stage must not force an early SRS review.
              await expect(service.createProgressivePlan(userId, stage)).rejects.toThrow(
                '没有带可用释义',
              );
              await prisma.userWordProgress.update({
                where,
                data: { nextReviewAt: new Date(Date.now() - 60_000) },
              });
            }
            const before = await prisma.userWordProgress.findUnique({ where });
            const plan = await service.createProgressivePlan(userId, stage);
            expect(plan.words).toHaveLength(1);
            expect(await prisma.userWordProgress.findUnique({ where })).toEqual(before);
            const item = await prisma.studyPlanItem.findFirstOrThrow({
              where: { planId: plan.id },
            });
            expect(item.source).toBe(stageIndex === 0 ? 'NEW' : 'REVIEW');
            expect(item.targetQuestionType).toBe(materials[stage].questions[0].type);
            const callsBefore = ai.generateForUser.mock.calls.length;
            await service.generatePlan(userId, plan.id);
            expect(ai.generateForUser.mock.calls.length - callsBefore).toBe(
              learnerIndex === 0 ? 1 : 0,
            );
            const link = await prisma.studyPlanItem.findUniqueOrThrow({ where: { id: item.id } });
            expect((link.question as { type: string }).type).toBe(
              materials[stage].questions[0].type,
            );
            linkedCaches.push(link.contentCacheId!);
            if (!caches.includes(link.contentCacheId!)) {
              caches.push(link.contentCacheId!);
              signatures.push(
                (
                  await prisma.studyContentCache.findUniqueOrThrow({
                    where: { id: link.contentCacheId! },
                  })
                ).signature,
              );
            }
            expect(await prisma.wordReviewAttempt.count({ where: { userId } })).toBe(stageIndex);
            // Different outcomes share the same unlock rule, but retain different
            // correctness evidence; neither outcome automatically marks mastery.
            await service.completeGroup(userId, plan.id, item.groupIndex, [
              {
                bookWordId,
                selectedAnswer: [materials[stage].questions[0].options[learnerIndex === 0 ? 0 : 1]],
              },
            ]);
            const after = await prisma.userWordProgress.findUniqueOrThrow({ where });
            expect(after.totalAttempts).toBe(stageIndex + 1);
            expect(after.correctAttempts).toBe(learnerIndex === 0 ? stageIndex + 1 : 0);
            expect(after.nextReviewAt!.getTime()).toBeGreaterThan(Date.now());
            expect(await prisma.userMasteredWord.count({ where: { userId } })).toBe(0);
            expect((await service.getProgressivePath(userId)).highestUnlockedStage).toBe(
              stageIndex === 0 ? 'context' : 'transfer',
            );
          }
          expect(new Set(linkedCaches).size).toBe(1);
        }
        expect(new Set(caches).size).toBe(3);
        expect(new Set(signatures).size).toBe(3);
        expect(ai.generateForUser).toHaveBeenCalledTimes(3);
        // A previously wrong version remains eligible when its word is due,
        // even after the learner has unlocked and visited later stages.
        const retryUser = users[1];
        await prisma.userWordProgress.update({
          where: { userId_bookWordId: { userId: retryUser, bookWordId } },
          data: { nextReviewAt: new Date(0) },
        });
        const retry = await service.createProgressivePlan(retryUser, 'foundation');
        await service.generatePlan(retryUser, retry.id);
        const retryItem = await prisma.studyPlanItem.findFirstOrThrow({
          where: { planId: retry.id },
        });
        expect(retryItem.contentCacheId).toBe(caches[0]);
        expect(ai.generateForUser).toHaveBeenCalledTimes(3);
        await service.completeGroup(retryUser, retry.id, retryItem.groupIndex, [
          { bookWordId, selectedAnswer: ['修理'] },
        ]);
        expect((await service.getProgressivePath(retryUser)).highestUnlockedStage).toBe('transfer');
        expect(
          await prisma.userWordProgress.findUniqueOrThrow({
            where: { userId_bookWordId: { userId: retryUser, bookWordId } },
          }),
        ).toMatchObject({ totalAttempts: 4, correctAttempts: 1 });
        // Explicit mastery excludes even an overdue word; creating a plan must
        // neither clear that decision nor mutate its existing schedule.
        const userId = users[0];
        const where = { userId_bookWordId: { userId, bookWordId } };
        await prisma.userWordProgress.update({ where, data: { nextReviewAt: new Date(0) } });
        await prisma.userMasteredWord.create({ data: { userId, wordId } });
        const before = await prisma.userWordProgress.findUnique({ where });
        await expect(service.createProgressivePlan(userId, 'foundation')).rejects.toThrow(
          '没有带可用释义',
        );
        expect(await prisma.userWordProgress.findUnique({ where })).toEqual(before);
        expect(await prisma.studyPlan.count({ where: { userId } })).toBe(3);
      } finally {
        await prisma.studyPlan.deleteMany({ where: { userId: { in: users } } });
        await prisma.studyContentCache.deleteMany({ where: { id: { in: caches } } });
        await prisma.studyContentGenerationClaim.deleteMany({
          where: { signature: { in: signatures } },
        });
        await prisma.user.deleteMany({ where: { id: { in: users } } });
        if (bookId) await prisma.vocabularyBook.delete({ where: { id: bookId } });
        if (wordId) await prisma.vocabularyWord.delete({ where: { id: wordId } });
        await prisma.$disconnect();
      }
    }, 30_000);
  },
);
